def die(reason):
    sys.stderr.write("CONFLICTO: "+reason+"\n");sys.exit(2)
if len(sys.argv)<2 or sys.argv[1] not in ('--check','--apply','--restore'):
    sys.stderr.write('Uso: IMPE_CRM_PUBLIC=/ruta/public_html bash script --check|--apply|--restore [respaldo]\n');sys.exit(1)
mode=sys.argv[1]
raw_path=os.environ.get('IMPE_CRM_PUBLIC','')
if not raw_path:die('Define IMPE_CRM_PUBLIC.')
root=Path(raw_path).resolve()
if not (root/'index.php').is_file():die('La ruta no es el CRM.')
backup_dir=Path(os.environ.get('IMPE_CRM_BACKUPS',str(Path.home()/'impe-ventas-resultados-backups'))).resolve()
if backup_dir==root or backup_dir in root.parents or root in backup_dir.parents:
    die('Los respaldos deben estar fuera de la raiz del sitio.')
def checksum(blob):return hashlib.sha256(blob).hexdigest()
def get_file(name):
    file=root/name
    if file.is_symlink() or not file.is_file() or root not in file.resolve().parents:
        die('Archivo ausente o enlace no permitido: '+name)
    return file
def atomic(file,data,permissions):
    fd,temp=tempfile.mkstemp(prefix='.impe-ventas-',dir=str(file.parent))
    try:
        os.fchmod(fd,permissions)
        with os.fdopen(fd,'wb') as fp:
            fp.write(data);fp.flush();os.fsync(fp.fileno())
        os.replace(temp,str(file))
    finally:
        if os.path.exists(temp):os.unlink(temp)
if mode=='--restore':
    if len(sys.argv)!=3:die('Indica el respaldo exacto.')
    backup=Path(sys.argv[2]).resolve()
    if backup_dir not in backup.parents or backup.is_symlink():die('Respaldo no autorizado.')
    man=backup/'manifest.json'
    if not man.is_file():die('Falta el manifiesto.')
    rec=json.loads(man.read_text(encoding='utf-8'))
    if len(rec)!=len(SPEC) or set(x['path'] for x in rec)!=set(x['path'] for x in SPEC):
        die('Respaldo de otra publicacion.')
    queue=[]
    for entry in rec:
        file=get_file(entry['path'])
        original=(backup/entry['backup']).read_bytes()
        current=file.read_bytes()
        if checksum(original)!=entry['original_sha256']:die('Respaldo alterado: '+entry['path'])
        if checksum(current) not in (entry['original_sha256'],entry['applied_sha256']):
            die('El archivo fue editado tras la publicacion: '+entry['path'])
        queue.append((file,original,entry['mode'],checksum(current)==entry['applied_sha256']))
    for file,original,permissions,needed in queue:
        if needed:atomic(file,original,permissions)
    print('OK: restauracion exacta; sin cambios de BD, audio ni Analista.')
    sys.exit(0)
if len(sys.argv)!=2:die('Parametros adicionales no permitidos.')
changes=[]
for item in SPEC:
    file=get_file(item['path'])
    original=file.read_bytes()
    try:source=original.decode('utf-8')
    except UnicodeDecodeError:die('Codigo no UTF-8: '+item['path'])
    crlf=b'\r\n' in original
    normalized=source.replace('\r\n','\n')
    updated=normalized;old_count=0;new_count=0
    for old,new in item['patches']:
        if normalized.count(old)==1 and normalized.count(new)==0:
            updated=updated.replace(old,new,1);old_count+=1
        elif normalized.count(old)==0 and normalized.count(new)==1:
            new_count+=1
        else:
            die('Version incompatible o fragmento duplicado: '+item['path'])
    if old_count and new_count:die('Parche parcial detectado: '+item['path'])
    data=(updated.replace('\n','\r\n') if crlf else updated).encode('utf-8')
    changes.append(dict(path=item['path'],file=file,original=original,target=data,
                        permission=stat.S_IMODE(file.stat().st_mode),state='pendiente' if old_count else 'actualizado'))
for item in changes:print(item['path']+': '+item['state'])
count=sum(1 for item in changes if item['state']=='pendiente')
print('Archivos a modificar:',count)
if mode=='--check':
    print('OK: verificacion de solo lectura; sin cambios.')
    sys.exit(0)
if not count:
    print('OK: todos los archivos ya estan actualizados.')
    sys.exit(0)
backup_dir.mkdir(mode=0o700,parents=True,exist_ok=True)
os.chmod(str(backup_dir),0o700)
folder=Path(tempfile.mkdtemp(prefix='ventas-disponibilidad-resultado-',dir=str(backup_dir)))
os.chmod(str(folder),0o700)
manifest=[]
for i,item in enumerate(changes):
    name='%02d.bak'%i
    file=folder/name
    file.write_bytes(item['original'])
    os.chmod(str(file),0o600)
    manifest.append(dict(path=item['path'],backup=name,mode=item['permission'],
                         original_sha256=checksum(item['original']),applied_sha256=checksum(item['target'])))
man=folder/'manifest.json'
man.write_text(json.dumps(manifest,indent=2),encoding='utf-8')
os.chmod(str(man),0o600)
updated=[]
try:
    for item in changes:
        if item['state']!='pendiente':continue
        if item['file'].read_bytes()!=item['original']:
            die('Archivo editado durante la revision: '+item['path'])
        atomic(item['file'],item['target'],item['permission']);updated.append(item)
except BaseException:
    for item in reversed(updated):
        if checksum(item['file'].read_bytes())==checksum(item['target']):
            atomic(item['file'],item['original'],item['permission'])
    raise
print('OK: disponibilidad y registro previo publicados. Respaldo:',str(folder))
print('Sin modificaciones SQL, grabaciones, webhook receptor ni modulo Analista.')
